# pseudo: classify a cell and index a triangle table
def cube_index(corners, c):
    idx = 0
    for i, v in enumerate(corners):
        if v >= c: idx |= (1 << i)
    return idx  # 0..255 -> lookup in tri_table

def rk4_step(x, v, h):
    k1 = v(x)
    k2 = v(x + 0.5*h*k1)
    k3 = v(x + 0.5*h*k2)
    k4 = v(x + h*k3)
    return x + (h/6.0)*(k1 + 2*k2 + 2*k3 + k4)

def field_line_step(x, B, ds):
    b = B(x); b = b/np.linalg.norm(b)
    return x + ds*b  # use RK4 in practice
